import pandas as pd


def _is_null(v):
    try:
        return pd.isna(v)
    except (TypeError, ValueError):
        return v is None


def _neq(a, b):
    """NULL-aware inequality: NULL vs NULL -> not changed; NULL vs value -> changed."""
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null or b_null:
        return True
    return a != b


